TLM.f("Sancti/02-01",{"officium":"S. Ignatii Episcopi et Martyris","rule":["Gloria"],"fallback":"Commune/C2","sections":{"Introitus":[{"k":"ref","la":"Gal 6:14"},{"k":"text","la":"Mihi autem absit gloriári, nisi in Cruce Dómini nostri Jesu Christi: per quem mihi mundus crucifíxus est, et ego mundo."},{"k":"ref","la":"Ps 131:1"},{"k":"text","la":"Meménto, Dómine, David: et omnis mansuetúdinis ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Mihi autem absit gloriári, nisi in Cruce Dómini nostri Jesu Christi: per quem mihi mundus crucifíxus est, et ego mundo."}],"Oratio":[{"k":"text","la":"Infirmitátem nostram réspice, omnípotens Deus: et, quia pondus própriæ actiónis gravat, beáti Ignátii Mártyris tui atque Pontíficis intercéssio gloriósa nos prótegat."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epistolæ beáti Pauli Apóstoli ad Romános"},{"k":"ref","la":"Rom 8:35-39"},{"k":"text","la":"Fratres: Quis nos separábit a caritáte Christi: tribulátio, an angustia, an fames, an núditas, an perículum, an persecútio, an gládius? sicut scriptum est: Quia propter te mortificámur tota die: æstimáti sumus sicut oves occisiónis. Sed in his ómnibus superámus propter eum, qui diléxit nos. Certus sum enim, quia neque mors, neque vita, neque ángeli, neque principátus, neque virtútes, neque instántia, neque futúra, neque fortitúdo, neque altitúdo, neque profúndum, neque creatúra alia poterit nos separáre a caritáte Dei, quæ est in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Eccli 44:16"},{"k":"text","la":"Ecce sacérdos magnus, qui in diébus suis plácuit Deo."},{"k":"ref","la":"Eccli 44:20"},{"k":"text","la":"Non est invéntus símilis illi, qui conserváret legem Excélsi. Allelúja, allelúja","mark":"V"},{"k":"ref","la":"Gal 2:19-20"},{"k":"text","la":"Christo confíxus sum Cruci: vivo ego, jam non ego, vivit vero in me Christus. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Gal 2:19-20"},{"k":"text","la":"Christo confíxus sum Cruci: vivo ego, jam non ego, vivit vero in me Christus. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Domine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Tractus":[{"k":"ref","la":"Eccli 44:16"},{"k":"text","la":"Ecce sacérdos magnus, qui in diébus suis plácuit Deo."},{"k":"ref","la":"Eccli 44:20"},{"k":"text","la":"Non est invéntus símilis illi, qui conserváret legem Excélsi."},{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei: et voluntáte labiórum ejus non fraudásti eum."},{"k":"text","la":"Quoniam prævenísti eum in benedictiónibus dulcedinis.","mark":"V"},{"k":"text","la":"Posuísti in cápite ejus coronam de lápide pretióso.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joann 12:24-26"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Amen, amen, dico vobis, nisi granum fruménti cadens in terram, mórtuum fúerit, ipsum solum manet: si autem mórtuum fúerit, multum fructum affert. Qui amat ánimam suam, perdet eam: et qui odit ánimam suam in hoc mundo, in vitam ætérnam custódit eam. Si quis mihi mínistrat, me sequátur: et ubi sum ego, illic et miníster meus erit. Si quis mihi ministráverit, honorificábit eum Pater meus."}],"Offertorium":[{"k":"ref","la":"Ps 8:6-7"},{"k":"text","la":"Glória et honore coronásti eum: et constituísti eum super ópera mánuum tuárum, Dómine."}],"Secreta":[{"k":"text","la":"Hóstias tibi, Dómine, beáti Ignátii Mártyris tui atque Pontíficis dicátas méritis, benígnus assúme: et ad perpétuum nobis tríbue proveníre subsídium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"text","la":"Fruméntum Christi sum: déntibus bestiárum molar, ut panis mundus invéniar."}],"Postcommunio":[{"k":"text","la":"Refécti participatióne múneris sacri, quaésumus, Dómine Deus noster: ut, cuius exséquimur cultum, intercedénte beáto Ignátio Mártyre tuo atque Pontífice, sentiámus efféctum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"c71f03f4dd2796ad":{"t":"Gal 6, 14, Ps 131, 1\n(Gal 6, 14) Daleko od mene da bih se ičim drugim hvalio osim križem Gospodina našega Isusa Krista, po kojem je meni svijet razapet, a ja svijetu. (Ps 131, 1) Spomeni se, Gospodine, Davida i sve njegove krotkosti.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Gal 6, 14) Daleko od mene da bih se ičim drugim hvalio osim križem Gospodina našega Isusa Krista, po kojem je meni svijet razapet, a ja svijetu.","kn":"(Gal. 6, 14). A ja ću se hvaliti samo križem Gospodina našega Isusa Krista, po kojemu je meni svijet raziapet i ja svijetu. (Ps. 131, 1) Sjeti se, Gospodine, Davida, i sve njegove pobožnosti. Slava Ocu ... A ja . . ,","knRef":"Kniewald 1942, str. 496–497 (snimka 249) (OCR)"},"376c16e11d5e8264":{"t":"<i>Pomolimo se</i>.\nObazri se, Gospodine, na našu slabost, pa jer naš pritište težina vlastitog djelovanja, neka nas štiti slavni zagovor blaženoga Ignacija, tvoga mučenika i biskupa.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Obazri, se, svemogući Bože, na slalbost Tvojih vjernika, koje pritište teret vlastitih čina i podaj, da nas zaštiti slavni zagovor blaženog I., Tvoga mučenika i biskupa. Po G. n.","knRef":"Kniewald 1942, str. 804–805 (snimka 403) (OCR)"},"edaf3a52c5220f54":{"t":"Rom 8, 35-39\nČitanje Poslanice bl. Pavla apostola Rimljanima. Braćo, tko će nas rastaviti od Kristove ljubavi? Možda nevolja ili stiska ili glad ili golotinja ili pogibelj ili progonstvo ili mač? (Kao što je pisano: Zbog tebe nas neprestano ubijaju, drže nas kao ovce za klanje). Ali u svemu tome mi pobjeđujemo, po onome, koji nas ljubi. Uvjeren sam, da ni smrt, ni život, ni anđeli, ni vlast, ni sile, ni sadašnjost, ni budućnost, ni jakost, ni visina, ni dubina, niti bi nas ista drugo moglo rastaviti od Božje ljubavi, koja je u Isusu Kristu Gospodinu našemu.","kn":"Čitanje poslanice bi. Pavla apostola (8 35-39). Braćo! Tko ce nas rastaviti od Kri.. ^ ljubavi? Možda nevolja ili stiska ili glad ili golotinja ili pogibelj ili progonstvo ili mac? Kao sto je piramc- Oni nas usmrčuju radi tebe cijeli dan, dize nas kao ovce za klanje. Ali u svemu ovomu pobjeđujemo po onomu, koji nas ljubi. Jer uvjeren, ;Sam, da hi smrt ni život ni anđeli ni poglavarstva ni sile ni sadašnjost ni budućnost ni jakost m visina m dubina niti kakav drugi stvor ne će nas moci rastaviti od Božje ljubavi, koja je u Isusu Kristu, Gospodinu našemu.","knRef":"Kniewald 1942, str. 496–497 (snimka 249) (OCR)"},"3c5f8512592234ed":{"t":"Sir 44, 16, Sir 44, 20\n(Sir 44, 16) Evo velikog svećenika koje se za svoga života svidio Bogu. (Sir 44, 20) Nitko mu nije bio ravan u izvršavanju zakona Svevišnjega.\n\nPs 20, 3-4\nTi si mu ispunio želju njegova srca i nisi mu uskratio molbe njegovih usana. Pretekao si ga slatkim blagoslovom. Postavio si mu na glavu vijenac od dragog kamenja.","kn":"(Psi 44, 16). Evo velikog svećenika, koji je za svoga života bio Bogu mio. (Crkv. 44, 20). I nitko mu nije bio ravan u držanju zakona Višnjega.\n\n(Ps. 20, 3-4). Ti si mu ispunio želju njegova srca i nisi mu uskratio molbe njegovih usana. Predusreo si ga slatkim blagoslovom i njegovu si .glavu okrunio krunom dragoga kamenja,","knRef":"Kniewald 1942, str. 450–451 (snimka 226) (OCR)"},"78b08a2a7b5143a2":{"t":"Iv 12, 24-26\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme reče Isus svojim učenicima: Ako pšenično zrno koje padne na zemlju ne istrune, ostaje samo, a ako istrune, daje mnogo ploda. Tko ljubi svoj život izgubit će ga. a tko prezire svoj život na ovome svijetu čuva ga za vječni život. Tko meni služi, neka ide za mnom, i gdje sam ja bit će i moj sluga. Tko meni služi proslavit će ga moj Otac.","kn":"t Slijedi sveto evanđelje po Ivanu (12, 24-26). U ono vrijeme reče Isus svojim učenicima; Ako pšenično zrno, koje pade na zemlju, ne iistrune, ostaje samo,^ a ako istrne, daje mnogo ploda. Tko ljubi SVOJ život, izgubit će ga, a tko mrzi svoj život na ovomu svijetu, čuva ga za vječni život. Tko meni Sluga. Tko meni sluzi, pocastit će ga moj Otac.","knRef":"Kniewald 1942, str. 498–499 (snimka 250) (OCR)"},"b389ff84b79a6464":{"t":"Ps 8, 6-7\nOkrunio si ga slavom i čašću i postavio si ga nad djela svojih ruku, Gospodine.","kn":"(Ps. 8, 6-7). Okrunio si ga slavom i čašću i postavio si ga nad sva djela tvoja. Gospodine!","knRef":"Kniewald 1942, str. 790–791 (snimka 396) (OCR)"},"6ce41d8745eb2340":{"t":"Dobrostivo primi, Gospodine:, prinose koje ti posvećujemo po zaslugama blaženog Ignacija, tvoga mučenika i biskupa i daj da nam postanu trajna pomoć.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, blagostivo žrtve, što Ti ih prinosimo zaslugama blaženoga I., Tvoga mučenika i biskupa i podaj, da nam ishode neprestanu Tvoju pomoć. Po G. n.","knRef":"Kniewald 1942, str. 804–805 (snimka 403) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"00a22fbed600f960":{"t":"Pšenica sam Kristova. Neka me samelju zubi zvijeri, da postanem pravi kruh."},"2f733afdb2eb55aa":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni sudjelovanjem u svetom daru, molimo, Gospodine Bože naš, da po zagovoru blaženog Ignacija, tvoga mučenika i biskupa osjetimo učinak tajne, koju slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Okrijepljeni svetim darovima molimo Te, Gospodine, Bože naš, da zagovorom blaženoga I., Tvoga mučenika i biskupa, osjetimo djelovanje svetih tajna, koje izvršuijemo. Po G. n.","knRef":"Kniewald 1942, str. 790–791 (snimka 396) (OCR)"},"1d6fcf234c5e03c2":{"t":"Sir 44, 16, Sir 44, 20\n(Sir 44, 16) Evo velikog svećenika koje se za svoga života svidio Bogu. (Sir 44, 20) Nitko mu nije bio ravan u izvršavanju zakona Svevišnjega.\n\nGal 2, 19-20\n<i>Aleluja</i>, <i>aleluja</i>.\nS Kristom sam na križ razapet. Živim ja, ali to više nisam ja, nego živi u meni Krist. <i>Aleluja</i>.","kn":"(Psi 44, 16). Evo velikog svećenika, koji je za svoga života bio Bogu mio. (Crkv. 44, 20). I nitko mu nije bio ravan u držanju zakona Višnjega.\n\nAleluja, aleluja.. (Gal. 2, 19, 20). S Kristom sam razapet na knz; ne živim više ja, nego živi u meni Krist, aleluja.","knRef":"Kniewald 1942, str. 450–451 (snimka 226) (OCR)"}}});
